    /* --- Projekt ausgeben --- */
    'pm.projektExport': { de:'Projekt ausgeben …', en:'Export project …', zh:'导出项目 …', hi:'परियोजना निर्यात …', es:'Exportar proyecto …', ar:'تصدير المشروع …', fr:'Exporter le projet …', bn:'প্রকল্প রপ্তানি …', pt:'Exportar projeto …', id:'Ekspor proyek …', ur:'منصوبہ برآمد …' },
    'ex.projektTitel':  { de:'Projekt ausgeben', en:'Export project', zh:'导出项目', hi:'परियोजना निर्यात', es:'Exportar proyecto', ar:'تصدير المشروع', fr:'Exporter le projet', bn:'প্রকল্প রপ্তানি', pt:'Exportar projeto', id:'Ekspor proyek', ur:'منصوبہ برآمد' },
    'ex.projektText':   { de:'Als Ordner voller Markdown-Dateien: eine Datei je Eintrag, sortiert wie in der Ordner-Ansicht. Lesbar mit jedem Texteditor, unabhängig von Sluuw.\n\nAls JSON: eine einzige Datei mit allem, zum Wiedereinlesen gedacht.', en:'As a folder of Markdown files: one file per entry, sorted as in the folder view. Readable in any text editor, independent of Sluuw.\n\nAs JSON: a single file containing everything, meant for importing back.', zh:'导出为 Markdown 文件夹：每个条目一个文件，按文件夹视图排序，任何文本编辑器都能读，不依赖 Sluuw。\n\n导出为 JSON：单个文件包含全部内容，便于再次导入。', hi:'Markdown फ़ोल्डर के रूप में: प्रति प्रविष्टि एक फ़ाइल, फ़ोल्डर-दृश्य के क्रम में। किसी भी टेक्स्ट एडिटर में पढ़ने योग्य, Sluuw से स्वतंत्र।\n\nJSON के रूप में: सब कुछ एक फ़ाइल में, फिर से आयात करने के लिए।', es:'Como carpeta de archivos Markdown: un archivo por entrada, ordenado como en la vista de carpetas. Legible en cualquier editor, sin depender de Sluuw.\n\nComo JSON: un único archivo con todo, pensado para volver a importarlo.', ar:'كمجلد من ملفات Markdown: ملف لكل مدخل، مرتّب كما في عرض المجلدات. يُقرأ بأي محرر نصوص، بمعزل عن Sluuw.\n\nكـJSON: ملف واحد يضم كل شيء، مُعدّ لإعادة الاستيراد.', fr:'Sous forme de dossier de fichiers Markdown : un fichier par entrée, classé comme dans la vue Dossiers. Lisible dans n’importe quel éditeur, indépendamment de Sluuw.\n\nEn JSON : un seul fichier contenant tout, prévu pour être réimporté.', bn:'Markdown ফোল্ডার হিসেবে: প্রতি এন্ট্রিতে একটি ফাইল, ফোল্ডার-দৃশ্যের ক্রমে। যেকোনো টেক্সট এডিটরে পড়া যায়, Sluuw ছাড়াই।\n\nJSON হিসেবে: সবকিছু একটি ফাইলে, আবার আমদানির জন্য।', pt:'Como pasta de ficheiros Markdown: um ficheiro por entrada, ordenado como na vista de pastas. Legível em qualquer editor, independente do Sluuw.\n\nComo JSON: um único ficheiro com tudo, pensado para reimportar.', id:'Sebagai folder berisi berkas Markdown: satu berkas per entri, tersusun seperti pada tampilan folder. Dapat dibaca di editor teks mana pun, tanpa Sluuw.\n\nSebagai JSON: satu berkas berisi semuanya, untuk diimpor kembali.', ur:'Markdown فائلوں کے فولڈر کے طور پر: فی اندراج ایک فائل، فولڈر منظر کی ترتیب میں۔ کسی بھی ٹیکسٹ ایڈیٹر میں پڑھی جا سکتی ہے، Sluuw کے بغیر بھی۔\n\nJSON کے طور پر: سب کچھ ایک فائل میں، دوبارہ درآمد کے لیے۔' },
    'ex.alsOrdner':     { de:'Markdown-Ordner', en:'Markdown folder', zh:'Markdown 文件夹', hi:'Markdown फ़ोल्डर', es:'Carpeta Markdown', ar:'مجلد Markdown', fr:'Dossier Markdown', bn:'Markdown ফোল্ডার', pt:'Pasta Markdown', id:'Folder Markdown', ur:'Markdown فولڈر' },
