    'mm.medienZoom':    { de:'Doppelklick auf Bild oder Video zeigt es groß.', en:'Double-click an image or video to show it large.', zh:'双击图片或视频可放大查看。', hi:'चित्र या वीडियो पर डबल-क्लिक उसे बड़ा दिखाता है।', es:'Doble clic en una imagen o vídeo para verlo en grande.', ar:'النقر المزدوج على صورة أو فيديو يعرضه بحجم كبير.', fr:'Double-cliquez une image ou une vidéo pour l’afficher en grand.', bn:'ছবি বা ভিডিওতে ডাবল-ক্লিক করলে বড় দেখায়।', pt:'Duplo clique numa imagem ou vídeo mostra-o em grande.', id:'Klik ganda gambar atau video untuk melihatnya besar.', ur:'تصویر یا ویڈیو پر ڈبل کلک اسے بڑا دکھاتا ہے۔' },
    'mm.hinweis2':      { de:'Ziehen = verschieben · Leere Fläche ziehen = Ansicht bewegen · Doppelklick auf Text = umbenennen · Doppelklick auf Bild oder Video = groß anzeigen · Mausrad = Zoom', en:'Drag = move · drag empty space = pan · double-click text = rename · double-click image or video = show large · scroll wheel = zoom', zh:'拖动 = 移动 · 拖动空白 = 平移 · 双击文字 = 重命名 · 双击图片或视频 = 放大 · 滚轮 = 缩放', hi:'खींचें = हिलाएँ · खाली जगह खींचें = दृश्य घुमाएँ · पाठ पर डबल-क्लिक = नाम बदलें · चित्र/वीडियो पर डबल-क्लिक = बड़ा दिखाएँ · व्हील = ज़ूम', es:'Arrastrar = mover · arrastrar el fondo = desplazar · doble clic en texto = renombrar · doble clic en imagen o vídeo = ver en grande · rueda = zoom', ar:'السحب = تحريك · سحب الفراغ = تحريك العرض · نقر مزدوج على النص = إعادة تسمية · نقر مزدوج على صورة أو فيديو = عرض كبير · العجلة = تكبير', fr:'Glisser = déplacer · glisser le fond = déplacer la vue · double-clic sur le texte = renommer · double-clic sur image ou vidéo = afficher en grand · molette = zoom', bn:'টানুন = সরান · ফাঁকা জায়গা টানুন = দৃশ্য সরান · লেখায় ডাবল-ক্লিক = নাম বদলান · ছবি/ভিডিওতে ডাবল-ক্লিক = বড় দেখান · স্ক্রল = জুম', pt:'Arrastar = mover · arrastar o fundo = deslocar · duplo clique no texto = renomear · duplo clique em imagem ou vídeo = ver em grande · roda = zoom', id:'Seret = pindah · seret area kosong = geser · klik ganda teks = ganti nama · klik ganda gambar atau video = tampilkan besar · roda = zoom', ur:'گھسیٹیں = منتقل · خالی جگہ گھسیٹیں = منظر ہلائیں · متن پر ڈبل کلک = نام بدلیں · تصویر/ویڈیو پر ڈبل کلک = بڑا دکھائیں · وہیل = زوم' },

